swap:
"use client";

import { useEffect, useState } from "react";
import { motion, type PanInfo } from "motion/react";
export type SwapCard = {
  id: string;
  src: string;
  label: string;
};
type CardSwapProps = {
  cards: SwapCard[];
  /** Auto-cycle interval in ms. Omit to disable. */
  autoplay?: number;
  width?: number;
  height?: number;
};
const STEP_X = 34;
const STEP_Y = 16;
const STEP_Z = 70;
/** Pixels of drag (along the stack direction) needed to move one slot. */
const SLOT_DRAG = 55;
function move<T>(arr: T[], from: number, to: number) {
  const next = [...arr];
  const [item] = next.splice(from, 1);
  next.splice(to, 0, item!);
  return next;
}

/**
 * Card Swap — a 3D stack of cards.
 * • Drag any card right/up to push it deeper, left/down to pull it forward.
 * • Fling the front card away to send it to the back.
 * • Tap a card to bring it to the front.
 * Requires: `motion` (npm i motion)
 */
export function CardSwap({
  cards,
  autoplay,
  width = 220,
  height = 290
}: CardSwapProps) {
  const [order, setOrder] = useState(cards);
  const [dragId, setDragId] = useState<string | null>(null);
  const [target, setTarget] = useState<number | null>(null);
  const [hover, setHover] = useState(false);
  const n = order.length;
  const sendToBack = () => setOrder(o => o.length ? move(o, 0, o.length - 1) : o);
  useEffect(() => {
    if (!autoplay || dragId || hover) return;
    const t = setInterval(sendToBack, autoplay);
    return () => clearInterval(t);
  }, [autoplay, dragId, hover]);
  const targetFor = (i: number, info: PanInfo) => {
    const along = (info.offset.x - info.offset.y) / 2; // stack goes right & up
    return Math.max(0, Math.min(n - 1, i + Math.round(along / SLOT_DRAG)));
  };
  const onDragEnd = (i: number, info: PanInfo) => {
    const to = targetFor(i, info);
    const fling = Math.hypot(info.velocity.x, info.velocity.y) > 700;
    const far = Math.hypot(info.offset.x, info.offset.y) > 140;
    if (i === 0 && to === 0 && (fling || far)) sendToBack();else if (to !== i) setOrder(o => move(o, i, to));
    setDragId(null);
    setTarget(null);
  };

  // Shift the whole stack so its visual center sits in the middle.
  const cx = -((n - 1) * STEP_X) / 2;
  const cy = (n - 1) * STEP_Y / 2;
  return <div onPointerEnter={() => setHover(true)} onPointerLeave={() => setHover(false)} style={{
    perspective: 1400,
    width: width + n * STEP_X + 80,
    height: height + n * STEP_Y + 80
  }} className="relative grid place-items-center">
      <div className="relative" style={{
      width,
      height,
      transformStyle: "preserve-3d",
      transform: `translate(${cx}px, ${cy}px) rotateY(-26deg) rotateX(6deg)`
    }}>
        {order.map((card, i) => {
        const isDragged = dragId === card.id;
        return <motion.div key={card.id} className="absolute inset-0 cursor-grab touch-none select-none overflow-hidden active:cursor-grabbing" style={{
          zIndex: isDragged ? 100 : n - i,
          borderRadius: 18,
          border: "3px solid #fff",
          boxShadow: isDragged ? "0 30px 60px -20px rgba(0,0,0,.45)" : "0 18px 40px -18px rgba(0,0,0,.35)",
          background: "#e8e8e8"
        }} initial={false} animate={{
          x: i * STEP_X,
          y: -i * STEP_Y,
          z: -i * STEP_Z,
          opacity: i > 5 ? 0 : 1
        }} transition={{
          type: "spring",
          stiffness: 260,
          damping: 26
        }} drag dragSnapToOrigin dragElastic={0.7} dragMomentum={false} onDragStart={() => setDragId(card.id)} onDrag={(_, info) => setTarget(targetFor(i, info))} onDragEnd={(_, info) => onDragEnd(i, info)} onTap={() => !dragId && i !== 0 && setOrder(o => move(o, i, 0))} whileDrag={{
          scale: 1.05
        }}>
              <img src={card.src} alt={card.label} draggable={false} className="h-full w-full object-cover" />
              <span className="absolute bottom-3 left-3 rounded-full px-3 py-1 text-xs font-medium" style={{
            background: "#fff",
            color: "#111",
            boxShadow: "0 2px 8px rgba(0,0,0,.12)"
          }}>
                {card.label}
              </span>
              {isDragged && target !== null && <span className="absolute right-3 top-3 rounded-full px-2.5 py-1 font-mono text-[11px]" style={{
            background: "#111",
            color: "#fff"
          }}>
                  {target + 1} / {n}
                </span>}
            </motion.div>;
      })}
      </div>
    </div>;
}

tilt:
"use client";

import { motion, useMotionTemplate, useMotionValue, useSpring, useTransform } from "motion/react";

/**
 * Tilt Card — 3D tilt toward the cursor with a moving glare.
 * Requires: `motion`
 */
export function TiltCard({
  src,
  label
}: {
  src: string;
  label?: string;
}) {
  const mx = useMotionValue(0.5);
  const my = useMotionValue(0.5);
  const rx = useSpring(useTransform(my, [0, 1], [14, -14]), {
    stiffness: 180,
    damping: 18
  });
  const ry = useSpring(useTransform(mx, [0, 1], [-14, 14]), {
    stiffness: 180,
    damping: 18
  });
  const gx = useTransform(mx, v => `${v * 100}%`);
  const gy = useTransform(my, v => `${v * 100}%`);
  const glare = useMotionTemplate`radial-gradient(circle at ${gx} ${gy}, rgba(255,255,255,.55), transparent 55%)`;
  return <div style={{
    perspective: 900
  }}>
      <motion.div onPointerMove={e => {
      const r = e.currentTarget.getBoundingClientRect();
      mx.set((e.clientX - r.left) / r.width);
      my.set((e.clientY - r.top) / r.height);
    }} onPointerLeave={() => {
      mx.set(0.5);
      my.set(0.5);
    }} style={{
      rotateX: rx,
      rotateY: ry,
      border: "3px solid #fff",
      boxShadow: "0 24px 50px -20px rgba(0,0,0,.4)"
    }} className="relative h-64 w-48 overflow-hidden rounded-[18px]">
        <img src={src} alt={label ?? ""} draggable={false} className="h-full w-full object-cover" />
        <motion.div className="pointer-events-none absolute inset-0 mix-blend-overlay" style={{
        background: glare
      }} />
        {label && <span className="absolute bottom-3 left-3 rounded-full px-3 py-1 text-xs font-medium" style={{
        background: "#fff",
        color: "#111"
      }}>
            {label}
          </span>}
      </motion.div>
    </div>;
}

