"use client";

import { useRef } from "react";
import { motion, useMotionValue, useSpring } from "motion/react";

/**
 * Magnetic Button — follows the cursor when it's nearby, springs back on leave.
 * Requires: `motion`
 */
export function MagneticButton({
  children = "Hover me",
  strength = 0.4
}: {
  children?: React.ReactNode;
  strength?: number;
}) {
  const ref = useRef<HTMLButtonElement>(null);
  const x = useSpring(useMotionValue(0), {
    stiffness: 200,
    damping: 15
  });
  const y = useSpring(useMotionValue(0), {
    stiffness: 200,
    damping: 15
  });
  const onMove = (e: React.PointerEvent) => {
    const r = ref.current!.getBoundingClientRect();
    x.set((e.clientX - (r.left + r.width / 2)) * strength);
    y.set((e.clientY - (r.top + r.height / 2)) * strength);
  };
  const reset = () => {
    x.set(0);
    y.set(0);
  };
  return <motion.button ref={ref} onPointerMove={onMove} onPointerLeave={reset} style={{
    x,
    y,
    background: "#111",
    color: "#fff",
    boxShadow: "0 12px 30px -12px rgba(0,0,0,.5)"
  }} whileTap={{
    scale: 0.94
  }} className="rounded-full px-8 py-4 text-sm font-medium">
      {children}
    </motion.button>;
}

