"use client";

import { useRef } from "react";
import { motion, useMotionValue, useSpring, useTransform, type MotionValue } from "motion/react";

/**
 * Dock — macOS-style magnification on hover.
 * Requires: `motion`
 */
export function Dock({
  items
}: {
  items: {
    id: string;
    src: string;
    label: string;
  }[];
}) {
  const mouseX = useMotionValue(Infinity);
  return <div onPointerMove={e => mouseX.set(e.clientX)} onPointerLeave={() => mouseX.set(Infinity)} className="flex h-20 items-end gap-3 rounded-[22px] px-3 pb-3" style={{
    background: "rgba(255,255,255,.75)",
    boxShadow: "0 10px 30px -12px rgba(0,0,0,.25)",
    backdropFilter: "blur(12px)"
  }}>
      {items.map(it => <DockIcon key={it.id} mouseX={mouseX} {...it} />)}
    </div>;
}
function DockIcon({
  mouseX,
  src,
  label
}: {
  mouseX: MotionValue<number>;
  src: string;
  label: string;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const dist = useTransform(mouseX, x => {
    const r = ref.current?.getBoundingClientRect() ?? {
      x: 0,
      width: 0
    };
    return x - r.x - r.width / 2;
  });
  const size = useSpring(useTransform(dist, [-140, 0, 140], [48, 84, 48]), {
    stiffness: 260,
    damping: 18
  });
  return <motion.div ref={ref} style={{
    width: size,
    height: size
  }} className="overflow-hidden rounded-[14px]" title={label}>
      <img src={src} alt={label} draggable={false} className="h-full w-full object-cover" />
    </motion.div>;
}

