"use client";

import { useState } from "react";
import { motion, useMotionValue, useSpring, useReducedMotion, useTransform } from "motion/react";

/** A movable magnifying lens. Touch and drag also work. Requires motion. */
export function ImageLens({
  src,
  label
}: {
  src: string;
  label: string;
}) {
  const [visible, setVisible] = useState(false);
  const x = useMotionValue(50);
  const y = useMotionValue(50);
  const smoothX = useSpring(x, {
    stiffness: 450,
    damping: 35
  });
  const smoothY = useSpring(y, {
    stiffness: 450,
    damping: 35
  });
  const left = useTransform(smoothX, value => `${value}%`);
  const top = useTransform(smoothY, value => `${value}%`);
  const reduce = useReducedMotion();
  const [position, setPosition] = useState({
    x: 50,
    y: 50
  });
  const update = (event: React.PointerEvent<HTMLDivElement>) => {
    const rect = event.currentTarget.getBoundingClientRect();
    const px = Math.max(0, Math.min(100, (event.clientX - rect.left) / rect.width * 100));
    const py = Math.max(0, Math.min(100, (event.clientY - rect.top) / rect.height * 100));
    x.set(px);
    y.set(py);
    setPosition({
      x: px,
      y: py
    });
    setVisible(true);
  };
  return <div className="relative h-[250px] w-[300px] max-w-[calc(100%-40px)] touch-pan-y overflow-hidden rounded-lg border-[3px] border-card bg-card shadow-lg" tabIndex={0} role="img" aria-label={`${label}, magnified detail`} onPointerMove={update} onPointerDown={update} onPointerLeave={() => setVisible(false)} onFocus={() => setVisible(true)} onBlur={() => setVisible(false)}>
      <img src={src} alt={label} draggable={false} className="h-full w-full object-cover" />
      <motion.div className="pointer-events-none absolute h-[112px] w-[112px] -translate-x-1/2 -translate-y-1/2 rounded-full border-[3px] border-card bg-card shadow-xl" style={{
      left: reduce ? `${position.x}%` : left,
      top: reduce ? `${position.y}%` : top,
      backgroundImage: `url(${src})`,
      backgroundSize: "600px 500px",
      backgroundPosition: `${position.x}% ${position.y}%`
    }} animate={{
      opacity: visible ? 1 : 0,
      scale: visible ? 1 : 0.7
    }} transition={{
      duration: reduce ? 0 : 0.15
    }} />
    </div>;
}

trail:
"use client";

import { useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
type TrailImage = {
  id: string;
  src: string;
  label: string;
};
type Stamp = {
  key: number;
  image: TrailImage;
  x: number;
  y: number;
  rotate: number;
};

/** A trail of photographs following the pointer. Tap to stamp on touch screens. Requires motion. */
export function ImageTrail({
  images
}: {
  images: TrailImage[];
}) {
  const [stamps, setStamps] = useState<Stamp[]>([]);
  const counter = useRef(0);
  const last = useRef({
    x: -1000,
    y: -1000
  });
  const reduce = useReducedMotion();
  const stamp = (event: React.PointerEvent<HTMLDivElement>, force = false) => {
    const rect = event.currentTarget.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    if (!force && Math.hypot(x - last.current.x, y - last.current.y) < 45) return;
    const image = images[counter.current % images.length];
    if (!image) return;
    last.current = {
      x,
      y
    };
    const key = counter.current++;
    setStamps(previous => [...previous.slice(-5), {
      key,
      image,
      x,
      y,
      rotate: (key % 5 - 2) * 8
    }]);
  };
  return <div className="relative h-[290px] w-[400px] max-w-[calc(100%-32px)] overflow-hidden" aria-label="Photograph trail" onPointerMove={event => {
    if (event.pointerType !== "touch") stamp(event);
  }} onPointerDown={event => stamp(event, true)} onPointerLeave={() => {
    setStamps([]);
    last.current = {
      x: -1000,
      y: -1000
    };
  }}>
      <div className="pointer-events-none absolute inset-0 grid place-items-center font-mono text-xs text-muted-foreground" aria-hidden="true">B / A</div>
      <AnimatePresence>
        {stamps.map(item => <motion.img key={item.key} src={item.image.src} alt={item.image.label} draggable={false} className="pointer-events-none absolute h-[126px] w-[94px] rounded-lg border-[3px] border-card object-cover shadow-lg" style={{
        left: item.x - 47,
        top: item.y - 63,
        zIndex: item.key
      }} initial={{
        opacity: 0,
        scale: reduce ? 1 : 0.65,
        rotate: item.rotate
      }} animate={{
        opacity: 1,
        scale: 1
      }} exit={{
        opacity: 0,
        scale: reduce ? 1 : 0.85
      }} transition={{
        duration: reduce ? 0 : 0.25
      }} />)}
      </AnimatePresence>
    </div>;
}

