    p = useSpring(0.25, {
      stiffness: 60,
      damping: 18
    }),
    mx = useMotionValue(.5),
    my = useMotionValue(.5);
  const rotY = useSpring(useTransform(mx, [0, 1], [-14, 14]), {
      stiffness: 120,
      damping: 16
    }),
    rotX = useSpring(useTransform(my, [0, 1], [10, -10]), {
      stiffness: 120,
      damping: 16
    });
