 <Button asChild variant="ghost" className="absolute inset-0 h-full w-full rounded-2xl p-0 hover:bg-transparent" aria-label={locked ? "Restore card" : "Dissolve card"} aria-pressed={locked}><motion.button onClick={() => setLocked(l => !l)}><motion.div className="glass-surface absolute inset-0 overflow-hidden rounded-2xl text-left" style={{
